"use client";

/**
 * Avatar: a person's picture, or their initials when there is none.
 * Purpose: wraps Radix Avatar, which shows the fallback while the image loads or if it fails.
 *   Generated by shadcn, then re-themed to Grove. Owner: design system.
 * Props: Avatar (size "default" 40 px | "sm" 32 px), AvatarImage (src, alt), AvatarFallback (initials).
 * Responsive: fixed sizes. Accessibility: give the image an alt; initials are text, so they read aloud.
 * States: image, fallback. Dependencies: radix Avatar, cn.
 * Tests: controls.test.tsx; Design Lab "Navigation" (S2-T07).
 * UX reference: ds-navigation, avatar menu.
 */
import { cva, type VariantProps } from "class-variance-authority";
import { Avatar as AvatarPrimitive } from "radix-ui";
import type { ComponentProps } from "react";
import { cn } from "@/lib/cn";

const avatarStyles = cva("relative flex shrink-0 overflow-hidden rounded-pill select-none", {
  variants: { size: { default: "size-10", sm: "size-8" } },
  defaultVariants: { size: "default" },
});

type AvatarProps = ComponentProps<typeof AvatarPrimitive.Root> & VariantProps<typeof avatarStyles>;

function Avatar({ className, size, ...props }: AvatarProps) {
  return (
    <AvatarPrimitive.Root
      data-slot="avatar"
      className={cn(avatarStyles({ size }), className)}
      {...props}
    />
  );
}

function AvatarImage({ className, ...props }: ComponentProps<typeof AvatarPrimitive.Image>) {
  return (
    <AvatarPrimitive.Image
      data-slot="avatar-image"
      className={cn("aspect-square size-full object-cover", className)}
      {...props}
    />
  );
}

function AvatarFallback({ className, ...props }: ComponentProps<typeof AvatarPrimitive.Fallback>) {
  return (
    <AvatarPrimitive.Fallback
      data-slot="avatar-fallback"
      className={cn(
        "flex size-full items-center justify-center rounded-pill bg-primary-tint text-small font-bold text-primary",
        className,
      )}
      {...props}
    />
  );
}

export { Avatar, AvatarFallback, AvatarImage };
